import { useEffect, useState } from 'react';
import { cents, dateAfter, dateTime, errorText, exportCSV, money, rpc, taipeiDate } from './lib/spa.js';
import { Empty, Field, Modal, MutationForm } from './OperationsShared.jsx';
import { StaffAccountForm, StaffArchiveForm, payLabel, staffRoleNames } from './StaffPortal.jsx';
import { exportPayrollXlsx } from './lib/payroll-xlsx.js';

const moduleLabels={dashboard:'營運首頁',bookings:'預約與日程',customers:'會員與儲值金',pos:'門店 POS',team:'人員與排班',payroll:'薪資與提成',catalog:'服務・商品・庫存',reviews:'評價',reports:'經營報表',access:'角色與權限',settings:'系統設定',self:'我的薪資與績效'};
const overtimeNames={weekday:'平日延長工時',rest_day:'休息日出勤',national_holiday:'國定／特別休假',regular_holiday:'例假日出勤'};

export function moduleName(id){return moduleLabels[id]||id;}

export function DashboardOS({data,onNavigate,allowed,onReload}){
 const [hoursModal,setHoursModal]=useState(false);
 const cards=[
  ['bookings','預約工作台','今日 '+data.appointments+' 筆預約，'+data.pending+' 筆待確認','◎'],
  ['customers','會員中心','今日新增 '+data.new_members+' 位會員','◇'],
  ['pos','門店 POS','商品銷售、庫存與收款','▣'],
  ['team','人員系統','今日排班 '+data.staff_working+' 人','♙'],
  ['payroll','薪資系統','工時、加班、提成與結算','＄'],
  ['catalog','目錄中心','服務、商品與官網同步','▤'],
  ['reviews','評價管理','療程評價與匿名建議','☆'],
  ['reports','經營報表','營收、客單與趨勢','↗'],
  ['access','角色權限','後台角色與功能授權','⌘'],
  ['settings','系統設定','門店、床位與預約規則','⚙'],
  ['self','我的薪資與績效','堂數、評價、提成與薪資','◈']
 ].filter(([id])=>allowed(id));
 const metrics=[['今日預約',data.appointments],['已完成',data.completed],['今日在班',data.staff_working],['啟用床位',data.rooms_active]];
 if(data.revenue_cents!=null)metrics.splice(2,0,['今日實收',money(data.revenue_cents)]);
 if(data.low_stock!=null)metrics.push(['低庫存商品',data.low_stock]);
 const today=data.today_hours||{};
 const saved=async()=>{setHoursModal(false);await onReload();};
 return <>
  <section className="os-hero"><div><p className="eyebrow">BUSINESS OPERATING SYSTEM</p><h2>今天的門店，一頁掌握</h2><p className="muted">{data.date} · Asia/Taipei · 所有數字直接來自正式營運資料</p></div><button className="primary" onClick={()=>onNavigate('bookings')}>開啟今日工作台</button></section>
  <div className="grid os-metrics">{metrics.map(([label,value])=><article className="card" key={label}><p className="muted">{label}</p><div className="metric">{value}</div></article>)}</div>
  <section className={`card os-today-hours ${today.is_open?'is-open':'is-closed'}`}><div><p className="eyebrow">TODAY · LIVE</p><h2>{today.is_open?'今日營業':'今日休假'}</h2><p>{today.is_open?`${minuteLabel(today.opening_minute)}–${minuteLabel(today.closing_minute)}`:'官網今日不提供新預約時段'}{today.note?` · ${today.note}`:''}</p><p className="muted">{today.source==='override'?'今日特殊設定，已即時同步官網與預約空檔。':'目前使用每週營業時間。'}</p></div>{allowed('settings')&&<button className="primary" onClick={()=>setHoursModal(true)}>設定今日營業／休假</button>}</section>
  <h2>系統直通車</h2><div className="os-launcher">{cards.map(([id,title,desc,icon])=><button key={id} onClick={()=>onNavigate(id)}><span className="os-icon">{icon}</span><span><strong>{title}</strong><small>{desc}</small></span></button>)}</div>
  <div className="split os-dashboard-lower"><section className="card"><h2>接下來的預約</h2>{!data.next_appointments.length&&<Empty>今天目前沒有有效預約。</Empty>}{data.next_appointments.map(row=><button className="os-list-button" key={row.id} onClick={()=>onNavigate('bookings')}><span><strong>{dateTime(row.starts_at)}</strong><small>{row.customer_name} · {row.service_name}</small></span><span>{row.staff_name}<br/><small>{row.resource_name}</small></span></button>)}</section><section className="card"><h2>今日提醒</h2><p>{data.pending?`還有 ${data.pending} 筆預約等待確認。`:'待確認預約已清空。'}</p><p>{data.cancelled?`今日取消或未到 ${data.cancelled} 筆。`:'今日沒有取消或未到。'}</p>{data.low_stock!=null&&<p>{data.low_stock?`${data.low_stock} 項商品已達低庫存門檻。`:'目前沒有低庫存提醒。'}</p>}<p>目前啟用 {data.rooms_active} 個服務床位。</p></section></div>
  {hoursModal&&<Modal title="今日營業狀態" onClose={()=>setHoursModal(false)}><DayOverrideForm date={data.date} value={today} saved={saved}/></Modal>}
 </>;
}

export function TeamOS({data,catalog,canManage,canAccounts,onReload}){
 const [modal,setModal]=useState(null),[query,setQuery]=useState(''),[archived,setArchived]=useState(false);
 const rows=data.staff.filter(s=>(archived||!s.archived_at)&&`${s.name} ${s.phone} ${s.title} ${s.employment_type_name}`.toLowerCase().includes(query.toLowerCase()));
 const roles=data.role_profiles||[];
 const saved=async()=>{setModal(null);await onReload();};
 return <>
  <div className="os-page-title"><div><h2>人員與排班</h2><p className="muted">人事資料、職稱、薪酬、服務能力、帳號與歷史績效都綁定同一位人員。</p></div>{canManage&&<button className="primary" onClick={()=>setModal({kind:'profile',row:null})}>新增人員</button>}</div>
  <div className="toolbar"><input aria-label="搜尋人員" placeholder="搜尋姓名、手機、職稱" value={query} onChange={e=>setQuery(e.target.value)}/><label className="auto-refresh"><input type="checkbox" checked={archived} onChange={e=>setArchived(e.target.checked)}/>顯示已封存</label></div>
  {!rows.length&&<Empty/>}<div className="grid os-team-grid">{rows.map(s=>{const account=data.accounts.find(a=>a.staff_id===s.id),shifts=data.shifts.filter(x=>x.staff_id===s.id),daily=(data.daily_shifts||[]).filter(x=>x.staff_id===s.id&&x.business_date>=taipeiDate()).slice(0,3);return <article className="card" key={s.id}><div className="os-person"><span className="os-avatar">{s.name.slice(0,1)}</span><div><h3>{s.name}</h3><p>{s.job_title_name||s.title} · {s.employment_type_name||'未設定'}</p></div></div><p>{s.phone||'未填手機'} · {s.email||'未填電子郵件'}</p><p>{payLabel(s)} · 提成 {(Number(s.commission_bps)/100).toFixed(2)}%</p><div className="row"><span className="badge">{s.active&&s.is_bookable&&!s.archived_at?'可接單':'不接單'}</span><span className="badge">{s.website_visible?'官網顯示':'官網隱藏'}</span></div><div className="os-shift-summary">{shifts.length?shifts.sort((a,b)=>a.weekday-b.weekday).map(sh=><small key={sh.id}>週{'日一二三四五六'[sh.weekday]} {minuteLabel(sh.start_minute)}–{minuteLabel(sh.end_minute)}</small>):<small>尚未設定每週排班</small>}</div>{daily.length>0&&<div className="os-daily-summary">{daily.map(sh=><small key={sh.id}>{sh.business_date} · {sh.is_working?`${minuteLabel(sh.start_minute)}–${minuteLabel(sh.end_minute)}`:'休班'}{sh.note?` · ${sh.note}`:''}</small>)}</div>}<p className="muted">登入：{account?`${account.username||'未命名'} · ${roles.find(r=>r.code===account.role)?.name||staffRoleNames[account.role]||account.role} · ${account.active?'啟用':'停用'}`:'尚未建立'}</p>{canManage&&<div className="actions"><button onClick={()=>setModal({kind:'profile',row:s})}>編輯檔案</button><button onClick={()=>setModal({kind:'daily',row:s})}>每日排班</button><button onClick={()=>setModal({kind:'shift',row:s})}>每週設定</button><button onClick={()=>setModal({kind:'off',row:s})}>休假／封鎖</button>{canAccounts&&account?.role!=='owner'&&<button onClick={()=>setModal({kind:'account',row:s,account})}>登入帳號</button>}{canAccounts&&account?.role!=='owner'&&<button onClick={()=>setModal({kind:'archive',row:s})}>{s.archived_at?'恢復':'封存'}</button>}</div>}</article>})}</div>
  <h2>每日排班</h2><p className="muted">指定日期排班會覆蓋每週設定，並即時控制該技師在前台是否有可預約時段。</p>{!(data.daily_shifts||[]).filter(x=>x.business_date>=taipeiDate()).length&&<Empty>尚未建立未來每日排班，系統目前使用每週設定。</Empty>}<div className="grid">{(data.daily_shifts||[]).filter(x=>x.business_date>=taipeiDate()).slice(0,28).map(sh=><article className="card" key={sh.id}><h3>{data.staff.find(s=>s.id===sh.staff_id)?.name||'已封存人員'} · {sh.business_date}</h3><p>{sh.is_working?`${minuteLabel(sh.start_minute)}–${minuteLabel(sh.end_minute)}`:'休班'}</p>{sh.note&&<p className="muted">{sh.note}</p>}{canManage&&<div className="actions"><button onClick={()=>setModal({kind:'daily',row:data.staff.find(s=>s.id===sh.staff_id),shift:sh})}>修改</button><button className="danger" onClick={()=>setModal({kind:'daily-delete',row:sh})}>恢復每週設定</button></div>}</article>)}</div>
  <h2>休假與特殊封鎖</h2><p className="muted">這些時段會立即從官網可預約時段排除；可用於請假、休息、訓練或特殊日期停班。</p>{!data.time_off.length&&<Empty>目前沒有休假或封鎖時段。</Empty>}<div className="grid">{data.time_off.map(t=><article className="card" key={t.id}><h3>{data.staff.find(s=>s.id===t.staff_id)?.name||'已封存人員'}</h3><p>{dateTime(t.starts_at)} ～ {dateTime(t.ends_at)}</p><p className="muted">{t.reason}</p>{canManage&&<button className="danger" onClick={()=>setModal({kind:'off-delete',row:t})}>刪除</button>}</article>)}</div>
  {modal&&<Modal title={{profile:modal.row?'編輯人員':'新增人員',account:'登入帳號與角色',archive:modal.row?.archived_at?'恢復人員':'封存人員',shift:'設定每週排班',daily:'設定每日排班','daily-delete':'恢復每週排班',off:'新增休假／封鎖時段','off-delete':'刪除休假／封鎖時段'}[modal.kind]} onClose={()=>setModal(null)}>{modal.kind==='profile'&&<StaffProfileForm row={modal.row} data={data} catalog={catalog} saved={saved}/>} {modal.kind==='account'&&<StaffAccountForm row={modal.row} account={modal.account} roles={roles} saved={saved}/>} {modal.kind==='archive'&&<StaffArchiveForm row={modal.row} saved={saved}/>} {modal.kind==='shift'&&<ShiftEditor row={modal.row} shifts={data.shifts.filter(x=>x.staff_id===modal.row.id)} saved={saved}/>} {modal.kind==='daily'&&<DailyShiftEditor row={modal.row} shift={modal.shift} saved={saved}/>} {modal.kind==='daily-delete'&&<MutationForm action={()=>rpc('spa_daily_shift_delete',{p_staff:modal.row.staff_id,p_date:modal.row.business_date})} onSaved={saved} submit="恢復每週設定"><p>{modal.row.business_date} 的每日覆蓋設定會刪除，前台將重新讀取該星期的預設排班。</p></MutationForm>} {modal.kind==='off'&&<TimeOffEditor row={modal.row} saved={saved}/>} {modal.kind==='off-delete'&&<MutationForm action={()=>rpc('spa_time_off_delete',{p_id:modal.row.id})} onSaved={saved} submit="確認刪除"><p>{modal.row.reason}</p><p className="alert">刪除後，這段時間將重新開放供預約引擎判斷。</p></MutationForm>}</Modal>}
 </>;
}

function StaffProfileForm({row,data,catalog,saved}){
 const initial=row||{name:'',name_en:'',title:'調理師',specialty:'',bio:'',phone:'',email:'',address:'',birth_date:'',hire_date:taipeiDate(),employment_type_code:'full_time',job_title_id:'',pay_basis:'monthly',base_pay_cents:null,commission_bps:0,active:true,is_bookable:true,website_visible:true,photo_url:''};
 const [f,setF]=useState(initial),[salary,setSalary]=useState(row?.base_pay_cents==null?'':String(row.base_pay_cents/100)),[services,setServices]=useState(row?catalog.skills.filter(x=>x.staff_id===row.id&&x.enabled!==false).map(x=>x.service_id):catalog.services.map(x=>x.id));
 const set=(key,value)=>setF(v=>({...v,[key]:value}));
 const payload={...f,id:row?.id||'',base_pay_cents:salary===''?'':cents(salary),commission_bps:Number(f.commission_bps),services};
 return <MutationForm action={()=>rpc('spa_staff_profile_save_v2',{p_payload:payload})} onSaved={saved}><div className="form-grid"><Field label="姓名"><input required maxLength="80" value={f.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="英文姓名"><input maxLength="80" value={f.name_en||''} onChange={e=>set('name_en',e.target.value)}/></Field><Field label="職稱"><select value={f.job_title_id||''} onChange={e=>{const title=data.job_titles.find(x=>x.id===e.target.value);setF(v=>({...v,job_title_id:e.target.value,title:title?.name||v.title}));}}><option value="">未設定</option>{data.job_titles.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="聘僱類型"><select value={f.employment_type_code||'full_time'} onChange={e=>set('employment_type_code',e.target.value)}>{data.employment_types.filter(x=>x.active).map(x=><option key={x.code} value={x.code}>{x.name}</option>)}</select></Field><Field label="手機"><input type="tel" value={f.phone||''} onChange={e=>set('phone',e.target.value)}/></Field><Field label="電子郵件"><input type="email" value={f.email||''} onChange={e=>set('email',e.target.value)}/></Field><Field label="生日"><input type="date" value={f.birth_date||''} onChange={e=>set('birth_date',e.target.value)}/></Field><Field label="到職日"><input type="date" value={f.hire_date||''} onChange={e=>set('hire_date',e.target.value)}/></Field><Field label="薪酬基準"><select value={f.pay_basis||'monthly'} onChange={e=>set('pay_basis',e.target.value)}><option value="monthly">月薪</option><option value="hourly">時薪</option><option value="session">每堂薪酬</option></select></Field><Field label="基本薪酬 NT$"><input type="number" min="0" step="0.01" value={salary} onChange={e=>setSalary(e.target.value)}/></Field><Field label="療程提成 %"><input type="number" min="0" max="100" step="0.01" value={Number(f.commission_bps)/100} onChange={e=>set('commission_bps',Math.round(Number(e.target.value)*100))}/></Field><Field label="頭像網址"><input type="url" value={f.photo_url||''} onChange={e=>set('photo_url',e.target.value)}/></Field><Field wide label="地址"><input value={f.address||''} onChange={e=>set('address',e.target.value)}/></Field><Field label="專長"><input value={f.specialty||''} onChange={e=>set('specialty',e.target.value)}/></Field><Field label="人員狀態"><select value={String(f.active)} onChange={e=>set('active',e.target.value==='true')}><option value="true">在職</option><option value="false">停用</option></select></Field><Field label="預約接單"><select value={String(f.is_bookable)} onChange={e=>set('is_bookable',e.target.value==='true')}><option value="true">可接單</option><option value="false">不接單</option></select></Field><Field label="官網顯示"><select value={String(f.website_visible)} onChange={e=>set('website_visible',e.target.value==='true')}><option value="true">顯示</option><option value="false">隱藏</option></select></Field><Field wide label="人員介紹"><textarea maxLength="2000" value={f.bio||''} onChange={e=>set('bio',e.target.value)}/></Field><Field wide label="可提供療程"><div className="os-check-grid">{catalog.services.map(s=><label key={s.id}><input type="checkbox" checked={services.includes(s.id)} onChange={e=>setServices(e.target.checked?[...services,s.id]:services.filter(id=>id!==s.id))}/>{s.name}</label>)}</div></Field></div></MutationForm>;
}

function minuteLabel(n){return `${n>=1440?'翌日 ':''}${String(Math.floor(n/60)%24).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function ShiftEditor({row,shifts,saved}){
 const [day,setDay]=useState(String(shifts[0]?.weekday??1)),current=shifts.find(x=>String(x.weekday)===day);
 const [start,setStart]=useState(current?.start_minute??600),[end,setEnd]=useState(current?.end_minute??1560);
 useEffect(()=>{const value=shifts.find(x=>String(x.weekday)===day);setStart(value?.start_minute??600);setEnd(value?.end_minute??1560);},[day]);
 const choices=Array.from({length:97},(_,i)=>i*30);
 return <MutationForm action={()=>rpc('spa_shift_save',{p_staff:row.id,p_weekday:Number(day),p_start:Number(start),p_end:Number(end)})} onSaved={saved}><p>{row.name} · 同一星期幾再次儲存會更新原排班。</p><div className="form-grid"><Field label="星期"><select value={day} onChange={e=>setDay(e.target.value)}>{[0,1,2,3,4,5,6].map(d=><option key={d} value={d}>週{'日一二三四五六'[d]}</option>)}</select></Field><Field label="開始"><select value={start} onChange={e=>setStart(Number(e.target.value))}>{choices.slice(0,49).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field><Field label="結束（可至翌日）"><select value={end} onChange={e=>setEnd(Number(e.target.value))}>{choices.filter(n=>n>start).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field></div><p className="muted">休息時間可在「休假／封鎖」建立；修改排班會立即影響官網空檔，但不會取消既有預約。</p></MutationForm>;
}
function DailyShiftEditor({row,shift,saved}){
 const [date,setDate]=useState(shift?.business_date||taipeiDate()),[working,setWorking]=useState(shift?.is_working??true),[start,setStart]=useState(shift?.start_minute??600),[end,setEnd]=useState(shift?.end_minute??1560),[note,setNote]=useState(shift?.note||'');
 const choices=Array.from({length:97},(_,i)=>i*30);
 return <MutationForm action={()=>rpc('spa_daily_shift_save',{p_staff:row.id,p_date:date,p_is_working:working,p_start:Number(start),p_end:Number(end),p_note:note})} onSaved={saved} submit="儲存每日排班"><p><strong>{row.name}</strong> · 此日期設定優先於每週設定，並立即聯動前台可預約時段。</p><div className="form-grid"><Field label="日期"><input type="date" required min={taipeiDate()} disabled={!!shift} value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="狀態"><select value={String(working)} onChange={e=>setWorking(e.target.value==='true')}><option value="true">上班／開放預約</option><option value="false">休班／不開放預約</option></select></Field>{working&&<><Field label="開始"><select value={start} onChange={e=>{const n=Number(e.target.value);setStart(n);if(n>=end)setEnd(Math.min(2880,n+60));}}>{choices.slice(0,49).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field><Field label="結束（可至翌日）"><select value={end} onChange={e=>setEnd(Number(e.target.value))}>{choices.filter(n=>n>start).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field></>}<Field wide label="備註"><input maxLength={500} value={note} onChange={e=>setNote(e.target.value)} placeholder={working?'例如：暫時早班':'例如：排休'}/></Field></div><p className="muted">若新排班會把既有預約排除在外，系統會阻止儲存；請先在預約頁更換或改期。</p></MutationForm>;
}
function TimeOffEditor({row,saved}){const [start,setStart]=useState(''),[end,setEnd]=useState(''),[reason,setReason]=useState('');return <MutationForm action={()=>rpc('spa_time_off_save',{p_staff:row.id,p_start:`${start}:00+08:00`,p_end:`${end}:00+08:00`,p_reason:reason})} onSaved={saved}><p>{row.name} · 台灣時間</p><div className="form-grid"><Field label="開始"><input type="datetime-local" required value={start} onChange={e=>setStart(e.target.value)}/></Field><Field label="結束"><input type="datetime-local" required value={end} onChange={e=>setEnd(e.target.value)}/></Field><Field wide label="原因"><input required maxLength="500" value={reason} onChange={e=>setReason(e.target.value)}/></Field></div></MutationForm>}

export function CatalogOS({data,canManage,onReload}){
 const [section,setSection]=useState('services'),[modal,setModal]=useState(null),[selected,setSelected]=useState([]),[query,setQuery]=useState('');
 const rows=(section==='services'?data.services:data.products).filter(x=>`${x.name} ${x.code||x.sku||''}`.toLowerCase().includes(query.toLowerCase()));
 const saved=async()=>{setModal(null);setSelected([]);await onReload();};
 const bulk=async action=>{if(!selected.length)return;await rpc('spa_catalog_bulk',{p_kind:section==='services'?'service':'product',p_ids:selected,p_action:action,p_value:null});setSelected([]);await onReload();};
 return <><div className="os-page-title"><div><h2>服務・商品・庫存</h2><p className="muted">這裡是官網、預約、POS 與薪資計算共用的唯一主資料。</p></div>{canManage&&<button className="primary" onClick={()=>setModal({kind:section==='services'?'service':'product',row:null})}>新增{section==='services'?'服務':'商品'}</button>}</div><nav><button className={section==='services'?'active':''} onClick={()=>{setSection('services');setSelected([]);}}>服務項目</button><button className={section==='products'?'active':''} onClick={()=>{setSection('products');setSelected([]);}}>商品與庫存</button></nav><div className="toolbar"><input aria-label="搜尋目錄" placeholder="搜尋名稱、代碼或 SKU" value={query} onChange={e=>setQuery(e.target.value)}/>{canManage&&selected.length>0&&<><span className="badge">已選 {selected.length}</span><button onClick={()=>bulk('publish')}>上架</button><button onClick={()=>bulk('hide')}>隱藏</button><button className="danger" onClick={()=>bulk('archive')}>封存</button></>}</div>{!rows.length&&<Empty/>}<div className="table-wrap"><table><thead><tr>{canManage&&<th>選取</th>}<th>名稱</th><th>{section==='services'?'時間':'SKU'}</th><th>售價</th><th>{section==='services'?'預約／官網':'庫存'}</th><th>狀態</th>{canManage&&<th>操作</th>}</tr></thead><tbody>{rows.map(row=><tr key={row.id}>{canManage&&<td><input aria-label={`選取${row.name}`} type="checkbox" checked={selected.includes(row.id)} onChange={e=>setSelected(e.target.checked?[...selected,row.id]:selected.filter(id=>id!==row.id))}/></td>}<td><strong>{row.name}</strong><small className="table-sub">{row.category_name||'未分類'} · {row.name_en}</small></td><td>{section==='services'?`${row.duration_minutes}+${row.buffer_minutes} 分`:row.sku}</td><td>{money(row.price_cents)}</td><td>{section==='services'?`${row.online_booking_enabled?'可預約':'不預約'}／${row.website_visible?'顯示':'隱藏'}`:<><span className={Number(row.inventory)<=Number(row.low_stock_threshold)?'alert-inline':''}>{row.inventory}</span> {row.unit_label}</>}</td><td><span className="badge">{{active:'上架',draft:'草稿',archived:'封存'}[row.status]}</span></td>{canManage&&<td><button onClick={()=>setModal({kind:section==='services'?'service':'product',row})}>編輯</button>{section==='products'&&<button onClick={()=>setModal({kind:'inventory',row})}>調庫存</button>}</td>}</tr>)}</tbody></table></div>{modal&&<Modal title={modal.kind==='inventory'?'庫存調整':`${modal.row?'編輯':'新增'}${modal.kind==='service'?'服務':'商品'}`} onClose={()=>setModal(null)}>{modal.kind==='service'&&<ServiceEditor row={modal.row} categories={data.service_categories} saved={saved}/>} {modal.kind==='product'&&<ProductEditor row={modal.row} categories={data.product_categories} saved={saved}/>} {modal.kind==='inventory'&&<InventoryEditor row={modal.row} saved={saved}/>}</Modal>}</>;
}

function ServiceEditor({row,categories,saved}){
 const [f,setF]=useState(row||{code:'',name:'',name_en:'',category_id:'',description:'',description_en:'',duration_minutes:45,buffer_minutes:15,price_cents:0,member_price_cents:'',image_url:'',status:'draft',online_booking_enabled:false,website_visible:false,display_order:0,website_content:{}});const set=(key,value)=>setF(v=>({...v,[key]:value}));
 const payload={...f,id:row?.id||'',price_cents:Number(f.price_cents),member_price_cents:f.member_price_cents===''?'':Number(f.member_price_cents),duration_minutes:Number(f.duration_minutes),buffer_minutes:Number(f.buffer_minutes),display_order:Number(f.display_order)};
 return <MutationForm action={()=>rpc('spa_service_save_v2',{p_payload:payload})} onSaved={saved}><div className="form-grid"><Field label="中文名稱"><input required value={f.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="英文名稱"><input value={f.name_en||''} onChange={e=>set('name_en',e.target.value)}/></Field><Field label="代碼"><input disabled={!!row} placeholder="留空自動建立" value={f.code||''} onChange={e=>set('code',e.target.value)}/></Field><Field label="分類"><select value={f.category_id||''} onChange={e=>set('category_id',e.target.value)}><option value="">未分類</option>{categories.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="療程分鐘"><input required type="number" min="15" max="480" value={f.duration_minutes} onChange={e=>set('duration_minutes',e.target.value)}/></Field><Field label="緩衝分鐘"><input required type="number" min="0" max="180" value={f.buffer_minutes} onChange={e=>set('buffer_minutes',e.target.value)}/></Field><Field label="售價（分）"><input required type="number" min="0" value={f.price_cents} onChange={e=>set('price_cents',e.target.value)}/></Field><Field label="會員價（分）"><input type="number" min="0" value={f.member_price_cents??''} onChange={e=>set('member_price_cents',e.target.value)}/></Field><Field label="狀態"><select value={f.status} onChange={e=>set('status',e.target.value)}><option value="draft">草稿</option><option value="active">上架</option><option value="archived">封存</option></select></Field><Field label="排序"><input type="number" value={f.display_order} onChange={e=>set('display_order',e.target.value)}/></Field><Field label="線上預約"><select value={String(f.online_booking_enabled)} onChange={e=>set('online_booking_enabled',e.target.value==='true')}><option value="true">開放</option><option value="false">關閉</option></select></Field><Field label="官網顯示"><select value={String(f.website_visible)} onChange={e=>set('website_visible',e.target.value==='true')}><option value="true">顯示</option><option value="false">隱藏</option></select></Field><Field wide label="中文介紹"><textarea value={f.description||''} onChange={e=>set('description',e.target.value)}/></Field><Field wide label="英文介紹"><textarea value={f.description_en||''} onChange={e=>set('description_en',e.target.value)}/></Field><Field wide label="圖片網址"><input type="url" value={f.image_url||''} onChange={e=>set('image_url',e.target.value)}/></Field></div><p className="muted">歷史預約會保留成交時的名稱、時間與價格快照；封存只影響新預約。</p></MutationForm>;
}

function ProductEditor({row,categories,saved}){
 const [f,setF]=useState(row||{sku:'',name:'',name_en:'',category_id:'',description:'',description_en:'',image_url:'',price_cents:0,cost_cents:'',barcode:'',unit_label:'',unit_label_en:'',low_stock_threshold:2,status:'draft',website_visible:false,store_visible:false,display_order:0});const set=(key,value)=>setF(v=>({...v,[key]:value}));
 const payload={...f,id:row?.id||'',price_cents:Number(f.price_cents),cost_cents:f.cost_cents===''?'':Number(f.cost_cents),low_stock_threshold:Number(f.low_stock_threshold),display_order:Number(f.display_order)};
 return <MutationForm action={()=>rpc('spa_product_save',{p_payload:payload})} onSaved={saved}><div className="form-grid"><Field label="SKU"><input required value={f.sku} onChange={e=>set('sku',e.target.value)}/></Field><Field label="條碼"><input value={f.barcode||''} onChange={e=>set('barcode',e.target.value)}/></Field><Field label="中文名稱"><input required value={f.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="英文名稱"><input value={f.name_en||''} onChange={e=>set('name_en',e.target.value)}/></Field><Field label="分類"><select value={f.category_id||''} onChange={e=>set('category_id',e.target.value)}><option value="">未分類</option>{categories.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="單位"><input value={f.unit_label||''} onChange={e=>set('unit_label',e.target.value)}/></Field><Field label="售價（分）"><input required type="number" min="0" value={f.price_cents} onChange={e=>set('price_cents',e.target.value)}/></Field><Field label="成本（分）"><input type="number" min="0" value={f.cost_cents??''} onChange={e=>set('cost_cents',e.target.value)}/></Field><Field label="低庫存門檻"><input type="number" min="0" value={f.low_stock_threshold} onChange={e=>set('low_stock_threshold',e.target.value)}/></Field><Field label="排序"><input type="number" value={f.display_order} onChange={e=>set('display_order',e.target.value)}/></Field><Field label="狀態"><select value={f.status} onChange={e=>set('status',e.target.value)}><option value="draft">草稿</option><option value="active">上架</option><option value="archived">封存</option></select></Field><Field label="官網／商店"><div className="row"><label><input type="checkbox" checked={f.website_visible} onChange={e=>set('website_visible',e.target.checked)}/>官網顯示</label><label><input type="checkbox" checked={f.store_visible} onChange={e=>set('store_visible',e.target.checked)}/>商店顯示</label></div></Field><Field wide label="中文介紹"><textarea value={f.description||''} onChange={e=>set('description',e.target.value)}/></Field><Field wide label="英文介紹"><textarea value={f.description_en||''} onChange={e=>set('description_en',e.target.value)}/></Field><Field wide label="圖片網址"><input type="url" value={f.image_url||''} onChange={e=>set('image_url',e.target.value)}/></Field></div></MutationForm>;
}
function InventoryEditor({row,saved}){const [quantity,setQuantity]=useState(''),[reason,setReason]=useState('');return <MutationForm action={()=>rpc('spa_inventory_adjustment',{p_product:row.id,p_delta:Number(quantity),p_reason:reason})} onSaved={saved}><p>{row.name} · 目前庫存 {row.inventory}</p><Field label="調整數量（增加為正數，扣除為負數）"><input required type="number" step="1" value={quantity} onChange={e=>setQuantity(e.target.value)}/></Field><Field label="原因"><textarea required maxLength="500" value={reason} onChange={e=>setReason(e.target.value)}/></Field></MutationForm>}

export function PayrollOS({data,staff,from,to,canManage,onReload}){
 const activeRuleId=data.rules.find(x=>x.status==='active')?.id||data.rules[0]?.id||'';
 const [modal,setModal]=useState(null),[rule,setRule]=useState(activeRuleId),[preview,setPreview]=useState(data.preview),[previewError,setPreviewError]=useState('');
 useEffect(()=>{setPreview(data.preview);},[data.preview]);
 useEffect(()=>{setRule(activeRuleId);},[activeRuleId]);
 useEffect(()=>{if(!rule)return;let live=true;setPreviewError('');rpc('spa_payroll_preview',{p_from:from,p_to:to,p_rule:rule}).then(rows=>{if(live)setPreview(rows);}).catch(error=>{if(live)setPreviewError(error.message||'薪資試算載入失敗');});return()=>{live=false;};},[rule,from,to]);
 const total=preview.reduce((sum,row)=>sum+Number(row.total_cents),0),settled=preview.reduce((n,r)=>n+Number(r.service_count),0),unsettled=preview.reduce((n,r)=>n+Number(r.unsettled_completed_count),0),productOrders=preview.reduce((n,r)=>n+Number(r.product_order_count),0);const selected=data.rules.find(x=>x.id===rule);
 const saved=async()=>{setModal(null);await onReload();};
 const exportRows=()=>exportCSV(`薪資試算_${from}_${to}.csv`,preview.map(r=>({員工:r.employee,職稱:r.role,聘僱:r.employment_type,薪酬基準:r.pay_basis,完成堂數:r.completed_count,已結帳堂數:r.service_count,待結帳堂數:r.unsettled_completed_count,退款堂數:r.refunded_service_count,服務分鐘:r.service_minutes,服務業績:r.service_sales_cents/100,商品訂單:r.product_order_count,商品業績:r.product_sales_cents/100,本薪:r.base_cents/100,療程提成:r.service_commission_cents/100,商品提成:r.product_commission_cents/100,指定獎金:r.designated_bonus_cents/100,加班費:r.overtime_cents/100,其他獎金:r.bonus_cents/100,津貼:r.allowance_cents/100,扣款:r.deduction_cents/100,應發合計:r.total_cents/100,警示:r.overtime_warning})));
 return <><div className="os-page-title"><div><h2>薪資與提成</h2><p className="muted">{from} ～ {to} · 每一列直接綁定人員檔案；療程堂數、收入與提成只計算由實際技師完成且已結帳、未退款的預約。</p></div><div className="actions"><button onClick={exportRows}>匯出 CSV</button><button onClick={()=>exportPayrollXlsx({rows:preview,from,to,rule:selected,rates:data.rates})}>匯出 XLSX</button>{canManage&&<button onClick={()=>setModal({kind:'overtime'})}>登錄加班</button>}{canManage&&<button onClick={()=>setModal({kind:'adjustment'})}>新增加扣項</button>}</div></div>
 <div className="card payroll-rule"><Field label="試算規則版本"><select value={rule} onChange={e=>setRule(e.target.value)}>{data.rules.map(x=><option key={x.id} value={x.id}>v{x.version_no} · {x.name} · {x.effective_from}</option>)}</select></Field><p>{selected?`月薪時薪基數除以 ${selected.hourly_divisor}；一般月加班上限 ${selected.monthly_overtime_limit_minutes/60} 小時，勞資會議同意上限 ${selected.agreed_monthly_limit_minutes/60} 小時。`:''}</p><p className="muted">已完成但尚未結帳的療程會列為待處理，不會提前進入堂數薪酬或提成。結算後保存人員、薪酬條件、實際技師與計算規則快照。</p>{canManage&&<div className="actions"><button onClick={()=>setModal({kind:'rule'})}>建立新版本</button>{selected?.status==='active'&&<button onClick={()=>setModal({kind:'components'})}>編輯倍率與階梯提成</button>}<button onClick={()=>rpc('spa_payroll_run_save',{p_from:from,p_to:to,p_rule:rule,p_finalize:false}).then(onReload)}>儲存草稿</button><button className="primary" onClick={()=>setModal({kind:'finalize'})}>確認結算並鎖定</button></div>}</div>
 {previewError&&<p role="alert" className="alert">{previewError}</p>}<div className="grid os-metrics"><article className="card"><p className="muted">本期人數</p><div className="metric">{preview.length}</div></article><article className="card"><p className="muted">已結帳完成</p><div className="metric">{settled}</div></article><article className="card"><p className="muted">完成待結帳</p><div className="metric">{unsettled}</div></article><article className="card"><p className="muted">計入商品訂單</p><div className="metric">{productOrders}</div></article><article className="card"><p className="muted">應發合計</p><div className="metric">{money(total)}</div></article></div>
 <div className="table-wrap"><table className="payroll-table"><thead><tr><th>員工／來源</th><th>完成／已結／待結</th><th>本薪</th><th>服務業績</th><th>療程提成</th><th>商品提成</th><th>指定獎金</th><th>加班費</th><th>獎金／津貼</th><th>扣款</th><th>應發</th></tr></thead><tbody>{preview.map(row=><tr key={row.staff_id}><td><strong>{row.employee}</strong><small className="table-sub">{row.role} · {row.pay_basis} · 檔案提成 {(Number(row.commission_bps)/100).toFixed(2)}%</small><button className="link-button" onClick={()=>setModal({kind:'detail',row})}>查看計算來源</button>{row.overtime_warning&&<small className="alert-inline">{row.overtime_warning}</small>}</td><td><strong>{row.completed_count} / {row.service_count} / {row.unsettled_completed_count}</strong><small className="table-sub">{row.service_minutes} 分 · 退款 {row.refunded_service_count} 堂</small></td><td>{money(row.base_cents)}</td><td>{money(row.service_sales_cents)}</td><td>{money(row.service_commission_cents)}</td><td>{money(row.product_commission_cents)}</td><td>{money(row.designated_bonus_cents)}</td><td>{money(row.overtime_cents)}</td><td>{money(Number(row.bonus_cents)+Number(row.allowance_cents))}</td><td>{money(row.deduction_cents)}</td><td><strong>{money(row.total_cents)}</strong></td></tr>)}</tbody></table></div>
 <h2>最近結算</h2>{!data.runs.length&&<Empty/>}<div className="grid">{data.runs.map(run=><article className="card" key={run.id}><h3>{run.period_start} ～ {run.period_end}</h3><p><span className="badge">{run.status==='finalized'?'已鎖定':'草稿'}</span></p>{canManage&&run.status==='finalized'&&<button onClick={()=>setModal({kind:'reopen',run})}>重開結算</button>}</article>)}</div>
 {modal&&<Modal title={{overtime:'登錄加班',adjustment:'薪資加扣項',rule:'建立薪資規則版本',components:'編輯加班倍率與階梯提成',finalize:'確認薪資結算',reopen:'重開薪資結算',detail:'薪資計算來源'}[modal.kind]} onClose={()=>setModal(null)}>{modal.kind==='overtime'&&<OvertimeForm staff={staff} saved={saved}/>} {modal.kind==='adjustment'&&<AdjustmentForm staff={staff} period={from} saved={saved}/>} {modal.kind==='rule'&&<RuleForm current={selected} saved={saved}/>} {modal.kind==='components'&&<PayrollComponentsForm rule={selected} data={data} saved={saved}/>} {modal.kind==='detail'&&<PayrollDetail row={modal.row} from={from} to={to}/>} {modal.kind==='finalize'&&<MutationForm action={()=>rpc('spa_payroll_run_save',{p_from:from,p_to:to,p_rule:rule,p_finalize:true})} onSaved={saved} submit="確認結算並鎖定"><p>將鎖定 {from} ～ {to} 的薪資試算，共 {preview.length} 人、{money(total)}。</p><p className="alert">鎖定後若要修改，必須填寫原因重開並留下稽核紀錄。</p></MutationForm>} {modal.kind==='reopen'&&<ReopenForm run={modal.run} saved={saved}/>}</Modal>}</>;
}
function PayrollDetail({row,from,to}){
 const [data,setData]=useState(null),[error,setError]=useState('');
 useEffect(()=>{let live=true;rpc('spa_payroll_staff_detail',{p_staff:row.staff_id,p_from:from,p_to:to}).then(value=>{if(live)setData(value);}).catch(e=>{if(live)setError(errorText(e));});return()=>{live=false;};},[row.staff_id,from,to]);
 if(error)return <p className="alert">{error}</p>;if(!data)return <Empty>正在載入來源記錄…</Empty>;
 return <><p><strong>{row.employee}</strong> · {row.role} · {from} ～ {to}</p><div className="grid"><article className="card"><p className="muted">完成／已結帳／待結帳</p><div className="metric">{row.completed_count} / {row.service_count} / {row.unsettled_completed_count}</div></article><article className="card"><p className="muted">服務收入／提成</p><div className="metric">{money(row.service_sales_cents)} / {money(row.service_commission_cents)}</div></article></div><h3>實際服務記錄</h3>{!data.services.length&&<Empty>本期沒有完成療程。</Empty>}<div className="table-wrap"><table><thead><tr><th>日期／預約</th><th>療程</th><th>狀態</th><th>收入</th><th>提成</th><th>評價</th></tr></thead><tbody>{data.services.map(item=><tr key={item.id}><td>{item.business_date}<small className="table-sub">{item.reference}</small></td><td>{item.service_name}<small className="table-sub">{item.service_minutes} 分</small></td><td><span className="badge">{{settled:'已結帳',unsettled:'待結帳',refunded:'已退款'}[item.settlement_status]}</span></td><td>{item.revenue_cents==null?'—':money(item.revenue_cents)}</td><td>{item.commission_cents==null?'—':money(item.commission_cents)}</td><td>{item.review_count}</td></tr>)}</tbody></table></div><h3>計入商品訂單</h3>{!data.product_orders.length&&<Empty>本期沒有計入商品訂單。</Empty>}{data.product_orders.map(item=><p key={`${item.id}-${item.name_snapshot}`}>{item.reference} · {item.name_snapshot} × {item.quantity} · {money(item.line_total_cents)} · 提成 {money(item.commission_cents)}</p>)}<p className="muted">每筆療程均按預約目前的實際技師計入；更換會留下原技師、實際技師、原因、操作人與提成變化紀錄。</p></>;
}
function OvertimeForm({staff,saved}){const [person,setPerson]=useState(staff[0]?.id||''),[date,setDate]=useState(taipeiDate()),[type,setType]=useState('weekday'),[minutes,setMinutes]=useState(60),[reason,setReason]=useState('');return <MutationForm action={()=>rpc('spa_overtime_save',{p_staff:person,p_date:date,p_type:type,p_minutes:Number(minutes),p_reason:reason})} onSaved={saved}><Field label="員工"><select required value={person} onChange={e=>setPerson(e.target.value)}>{staff.filter(x=>!x.archived_at).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="日期"><input required type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="加班類型"><select value={type} onChange={e=>setType(e.target.value)}>{Object.entries(overtimeNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></Field><Field label="分鐘"><input required type="number" min="1" max="720" value={minutes} onChange={e=>setMinutes(e.target.value)}/></Field><Field label="原因"><textarea required value={reason} onChange={e=>setReason(e.target.value)}/></Field></MutationForm>}
function AdjustmentForm({staff,period,saved}){const [person,setPerson]=useState(staff[0]?.id||''),[kind,setKind]=useState('bonus'),[amount,setAmount]=useState(''),[note,setNote]=useState('');return <MutationForm action={()=>rpc('spa_payroll_adjustment_save',{p_staff:person,p_period:period,p_kind:kind,p_cents:cents(amount),p_note:note})} onSaved={saved}><Field label="員工"><select value={person} onChange={e=>setPerson(e.target.value)}>{staff.filter(x=>!x.archived_at).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="類型"><select value={kind} onChange={e=>setKind(e.target.value)}><option value="bonus">獎金</option><option value="allowance">津貼</option><option value="deduction">扣款</option><option value="designated_bonus">指定客獎金</option></select></Field><Field label="金額 NT$"><input required type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><Field label="說明"><textarea required value={note} onChange={e=>setNote(e.target.value)}/></Field></MutationForm>}
function PayrollComponentsForm({rule,data,saved}){
 const metricNames={service_minutes:'服務分鐘',service_count:'服務堂數',service_sales_cents:'服務業績 NT$',product_sales_cents:'商品業績 NT$'};
 const [rates,setRates]=useState(data.rates.filter(x=>x.rule_version_id===rule.id).map(x=>({...x,multiplier_percent:Number(x.multiplier_bps)/100})));
 const [tiers,setTiers]=useState(data.tiers.filter(x=>x.rule_version_id===rule.id).map(x=>({...x,threshold_from_value:['service_sales_cents','product_sales_cents'].includes(x.metric)?Number(x.threshold_from)/100:Number(x.threshold_from),threshold_to_value:x.threshold_to==null?'':['service_sales_cents','product_sales_cents'].includes(x.metric)?Number(x.threshold_to)/100:Number(x.threshold_to),rate_percent:Number(x.rate_bps)/100})));
 const changeRate=(index,key,value)=>setRates(rows=>rows.map((row,i)=>i===index?{...row,[key]:value}:row));
 const changeTier=(index,key,value)=>setTiers(rows=>rows.map((row,i)=>i===index?{...row,[key]:value}:row));
 const addTier=()=>setTiers(rows=>[...rows,{metric:'service_minutes',threshold_from_value:0,threshold_to_value:'',rate_percent:0,service_category_id:null}]);
 const payloadRates=rates.map(({employment_type_code,overtime_type,start_minute,end_minute,multiplier_percent})=>({employment_type_code,overtime_type,start_minute:Number(start_minute),end_minute:Number(end_minute),multiplier_bps:Math.round(Number(multiplier_percent)*100)}));
 const payloadTiers=tiers.map(row=>{const scale=['service_sales_cents','product_sales_cents'].includes(row.metric)?100:1;return {metric:row.metric,threshold_from:Math.round(Number(row.threshold_from_value)*scale),threshold_to:row.threshold_to_value===''?null:Math.round(Number(row.threshold_to_value)*scale),rate_bps:Math.round(Number(row.rate_percent)*100),service_category_id:row.service_category_id||null};});
 return <MutationForm action={()=>rpc('spa_payroll_components_save',{p_rule:rule.id,p_rates:payloadRates,p_tiers:payloadTiers})} onSaved={saved} submit="儲存規則"><p>v{rule.version_no} · {rule.name}</p><p className="muted">只有目前啟用版本可編輯。建立新版本會複製這些規則；已鎖定的歷史結算保留原計算快照。</p><h3>加班倍率</h3><div className="table-wrap"><table><thead><tr><th>聘僱</th><th>類型</th><th>分鐘區間</th><th>倍率 %</th></tr></thead><tbody>{rates.map((row,index)=><tr key={`${row.employment_type_code}-${row.overtime_type}-${row.start_minute}`}><td>{row.employment_type_code==='full_time'?'全職':'兼職'}</td><td>{overtimeNames[row.overtime_type]}</td><td><div className="row"><input aria-label="開始分鐘" type="number" min="0" max="719" value={row.start_minute} onChange={e=>changeRate(index,'start_minute',e.target.value)}/><span>–</span><input aria-label="結束分鐘" type="number" min="1" max="720" value={row.end_minute} onChange={e=>changeRate(index,'end_minute',e.target.value)}/></div></td><td><input aria-label="加班倍率" type="number" min="0" max="1000" step="0.01" value={row.multiplier_percent} onChange={e=>changeRate(index,'multiplier_percent',e.target.value)}/></td></tr>)}</tbody></table></div><div className="os-page-title"><div><h3>提成階梯</h3><p className="muted">無階梯時使用人員檔案中的提成比例；有階梯時，系統按符合的最高門檻計算。</p></div><button type="button" onClick={addTier}>新增階梯</button></div>{!tiers.length&&<Empty>尚未設定階梯提成。</Empty>}<div className="table-wrap"><table><thead><tr><th>指標</th><th>起點</th><th>終點（留空為以上）</th><th>提成 %</th><th></th></tr></thead><tbody>{tiers.map((row,index)=><tr key={row.id||index}><td><select value={row.metric} onChange={e=>changeTier(index,'metric',e.target.value)}>{Object.entries(metricNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></td><td><input type="number" min="0" step="0.01" value={row.threshold_from_value} onChange={e=>changeTier(index,'threshold_from_value',e.target.value)}/></td><td><input type="number" min="0" step="0.01" value={row.threshold_to_value} onChange={e=>changeTier(index,'threshold_to_value',e.target.value)}/></td><td><input type="number" min="0" max="100" step="0.01" value={row.rate_percent} onChange={e=>changeTier(index,'rate_percent',e.target.value)}/></td><td><button type="button" className="danger" onClick={()=>setTiers(rows=>rows.filter((_,i)=>i!==index))}>刪除</button></td></tr>)}</tbody></table></div></MutationForm>;
}
function RuleForm({current,saved}){const [name,setName]=useState('薪資規則'),[date,setDate]=useState(taipeiDate()),[divisor,setDivisor]=useState(current?.hourly_divisor||240),[include,setInclude]=useState(current?.include_regular_commission??true),[monthly,setMonthly]=useState((current?.monthly_overtime_limit_minutes||2760)/60),[agreed,setAgreed]=useState((current?.agreed_monthly_limit_minutes||3240)/60),[quarter,setQuarter]=useState((current?.quarterly_overtime_limit_minutes||8280)/60);return <MutationForm action={()=>rpc('spa_payroll_rule_create',{p_name:name,p_effective:date,p_divisor:Number(divisor),p_include_commission:include,p_monthly_limit:Number(monthly)*60,p_agreed_limit:Number(agreed)*60,p_quarter_limit:Number(quarter)*60})} onSaved={saved}><Field label="版本名稱"><input required value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="生效日"><input required type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="月薪換算時薪除數"><input type="number" min="1" value={divisor} onChange={e=>setDivisor(e.target.value)}/></Field><Field label="時薪基數包含固定提成"><select value={String(include)} onChange={e=>setInclude(e.target.value==='true')}><option value="true">包含</option><option value="false">不包含</option></select></Field><Field label="一般月上限（小時）"><input type="number" min="1" value={monthly} onChange={e=>setMonthly(e.target.value)}/></Field><Field label="勞資會議月上限（小時）"><input type="number" min="1" value={agreed} onChange={e=>setAgreed(e.target.value)}/></Field><Field label="季度上限（小時）"><input type="number" min="1" value={quarter} onChange={e=>setQuarter(e.target.value)}/></Field><p className="muted">建立新版本會複製目前加班倍率與提成級距，歷史結算不受影響。</p></MutationForm>}
function ReopenForm({run,saved}){const [reason,setReason]=useState('');return <MutationForm action={()=>rpc('spa_payroll_reopen',{p_run:run.id,p_reason:reason})} onSaved={saved}><p>{run.period_start} ～ {run.period_end}</p><Field label="重開原因"><textarea required value={reason} onChange={e=>setReason(e.target.value)}/></Field></MutationForm>}

export function AccessOS({data,onReload}){
 const [modal,setModal]=useState(null);const saved=async()=>{setModal(null);await onReload();};
 return <><div className="os-page-title"><div><h2>角色與權限</h2><p className="muted">店主擁有完整後台權限。其他角色統一只能查看營運首頁、預約與日程、評價，以及自己的薪資與績效。</p></div><button className="primary" onClick={()=>setModal({})}>新增角色</button></div><div className="grid">{data.roles.map(role=><article className="card" key={role.code}><div className="row"><h3>{role.name}</h3>{role.system_role&&<span className="badge">系統角色</span>}</div><p className="muted">{role.code} · {role.active?'啟用':'停用'}</p><div className="os-permission-list">{role.permissions.map(code=><span className="badge" key={code}>{data.permissions.find(x=>x.code===code)?.name||code}</span>)}</div>{role.code!=='owner'&&<button onClick={()=>setModal(role)}>編輯角色</button>}</article>)}</div>{modal&&<Modal title={modal.code?'編輯角色':'新增角色'} onClose={()=>setModal(null)}><RoleForm row={modal} saved={saved}/></Modal>}</>;
}
function RoleForm({row,saved}){const [code,setCode]=useState(row.code||''),[name,setName]=useState(row.name||''),[active,setActive]=useState(row.active??true);const permissions=['dashboard.view','appointments.view','reviews.view'];return <MutationForm action={()=>rpc('spa_role_profile_save',{p_code:code,p_name:name,p_permissions:permissions,p_active:active,p_display_order:row.display_order||100})} onSaved={saved}><Field label="角色代碼"><input required disabled={!!row.code} pattern="[a-z][a-z0-9_]{1,31}" value={code} onChange={e=>setCode(e.target.value.toLowerCase())}/></Field><Field label="角色名稱"><input required value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="狀態"><select value={String(active)} onChange={e=>setActive(e.target.value==='true')}><option value="true">啟用</option><option value="false">停用</option></select></Field><fieldset><legend>員工固定權限</legend><div className="os-permission-list"><span className="badge">營運首頁</span><span className="badge">預約與日程</span><span className="badge">評價</span><span className="badge">自己的薪資與績效</span></div><p className="muted">這些權限由系統強制保護，不能擴充到會員、收支、人事、商品或系統設定。</p></fieldset></MutationForm>}

export function SettingsOS({data,onReload}){
 const [modal,setModal]=useState(null);const saved=async()=>{setModal(null);await onReload();};
 const today=data.business_overrides.find(x=>x.business_date===taipeiDate());
 return <>
  <div className="os-page-title"><div><h2>系統設定</h2><p className="muted">門店、官網、預約、庫存與資源設定集中管理。</p></div></div>
  <div className="grid">
   <article className="card"><h3>門店資料與營業時間</h3><p>{data.business.name}</p><p>{data.business.phone}</p><p>{data.business.address}</p><p className="muted">每週營業時間會同步官網和預約空檔；特殊日期優先。</p><div className="actions"><button onClick={()=>setModal({kind:'business'})}>修改資料</button><button className="primary" onClick={()=>setModal({kind:'hours'})}>每週營業時間</button><button onClick={()=>setModal({kind:'override',row:today,date:taipeiDate()})}>今日營業／休假</button></div></article>
   <article className="card"><h3>官網同步</h3><p>預約按鈕：{data.website.booking_cta?'顯示':'隱藏'}</p><p>人員：{data.website.show_staff?'顯示':'隱藏'} · 商品：{data.website.show_products?'顯示':'隱藏'}</p><button onClick={()=>setModal({kind:'website'})}>修改</button></article>
   <article className="card"><h3>預約規則</h3><p>{data.booking.booking_days} 天內 · {data.booking.auto_confirm?'自動確認':'人工確認'}</p><p>取消期限 {data.booking.cancellation_hours} 小時</p><button onClick={()=>setModal({kind:'booking'})}>修改</button></article>
   <article className="card"><h3>零庫存顯示</h3><p>{data.inventory.zero_stock_behavior==='hide'?'自動隱藏':'顯示售罄'}</p><button onClick={()=>setModal({kind:'inventory'})}>修改</button></article>
  </div>
  <section className="card os-hours-overrides"><div className="os-page-title"><div><h2>特殊日期</h2><p className="muted">用於休假、節日或當日延長營業；設定後立即覆蓋每週時間。</p></div><button onClick={()=>setModal({kind:'override',row:null,date:taipeiDate()})}>新增特殊日期</button></div>{!data.business_overrides.length&&<Empty>未來 180 天沒有特殊營業設定。</Empty>}<div className="row">{data.business_overrides.map(row=><button className="os-date-chip" key={row.business_date} onClick={()=>setModal({kind:'override',row,date:row.business_date})}><strong>{row.business_date}</strong><span>{row.is_open?`${minuteLabel(row.opening_minute)}–${minuteLabel(row.closing_minute)}`:'休假'}</span><small>{row.note||'當日設定'}</small></button>)}</div></section>
  <h2>服務資源</h2><p className="muted">目前使用「床位」作為資源；預約引擎依啟用資源數量阻止超賣。</p><div className="row">{data.resources.map(r=><article className="card" key={r.id}><h3>{r.name}</h3><span className="badge">{r.active?'啟用':'停用'}</span><button onClick={()=>setModal({kind:'room',row:r})}>修改</button></article>)}<button onClick={()=>setModal({kind:'room',row:null})}>新增床位</button></div>
  <ResetDataPanel onReload={onReload}/>
  {modal&&<Modal title={{business:'門店資料',hours:'每週營業時間',override:'特殊日期營業設定',website:'官網同步',inventory:'庫存顯示',booking:'預約規則',room:'床位設定'}[modal.kind]||'系統設定'} onClose={()=>setModal(null)}>{modal.kind==='business'&&<JsonSettingForm settingKey="business" value={data.business} fields={[["name","門店名稱"],["phone","電話"],["address","地址"],["timezone","時區"]]} saved={saved}/>} {modal.kind==='hours'&&<BusinessHoursForm value={data.business_hours} saved={saved}/>} {modal.kind==='override'&&<DayOverrideForm date={modal.date} value={modal.row} saved={saved}/>} {modal.kind==='website'&&<WebsiteSettingForm value={data.website} saved={saved}/>} {modal.kind==='inventory'&&<InventorySettingForm value={data.inventory} saved={saved}/>} {modal.kind==='booking'&&<BookingSettingForm value={data.booking} saved={saved}/>} {modal.kind==='room'&&<ResourceForm row={modal.row} saved={saved}/>}</Modal>}
 </>;
}

const timeChoices=Array.from({length:97},(_,i)=>i*30);
function BusinessHoursForm({value,saved}){
 const [rows,setRows]=useState([0,1,2,3,4,5,6].map(weekday=>value.find(x=>x.weekday===weekday)||{weekday,is_open:true,opening_minute:600,closing_minute:1560}));
 const change=(weekday,key,next)=>setRows(list=>list.map(row=>row.weekday===weekday?{...row,[key]:next,...(key==='opening_minute'&&next>=row.closing_minute?{closing_minute:Math.min(2880,next+60)}:{})}:row));
 return <MutationForm action={()=>rpc('spa_business_hours_save',{p_hours:rows})} onSaved={saved} submit="儲存每週營業時間"><p className="muted">結束時間可跨至翌日。修改後會立即影響官網顯示、新預約和顧客自行改期；既有預約保持不變。</p><div className="os-hours-grid">{rows.map(row=><div className={`os-hours-row ${row.is_open?'':'is-closed'}`} key={row.weekday}><strong>週{'日一二三四五六'[row.weekday]}</strong><label className="auto-refresh"><input type="checkbox" checked={row.is_open} onChange={e=>change(row.weekday,'is_open',e.target.checked)}/>{row.is_open?'營業':'休息'}</label><select aria-label={`週${'日一二三四五六'[row.weekday]}開始`} disabled={!row.is_open} value={row.opening_minute} onChange={e=>change(row.weekday,'opening_minute',Number(e.target.value))}>{timeChoices.slice(0,49).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select><span>至</span><select aria-label={`週${'日一二三四五六'[row.weekday]}結束`} disabled={!row.is_open} value={row.closing_minute} onChange={e=>change(row.weekday,'closing_minute',Number(e.target.value))}>{timeChoices.filter(n=>n>row.opening_minute).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></div>)}</div></MutationForm>;
}
function DayOverrideForm({date,value,saved}){
 const [day,setDay]=useState(value?.business_date||date||taipeiDate()),[isOpen,setOpen]=useState(value?.is_open??true),[opening,setOpening]=useState(value?.opening_minute??600),[closing,setClosing]=useState(value?.closing_minute??1560),[note,setNote]=useState(value?.note||''),[restoreBusy,setRestoreBusy]=useState(false),[restoreError,setRestoreError]=useState('');
 const hasOverride=value?.source==='override'||!!value?.business_date;
 async function restore(){setRestoreBusy(true);setRestoreError('');try{await rpc('spa_business_day_override_delete',{p_date:day});await saved();}catch(e){setRestoreError(errorText(e));setRestoreBusy(false);}}
 return <><MutationForm action={()=>rpc('spa_business_day_override_save',{p_date:day,p_is_open:isOpen,p_open:Number(opening),p_close:Number(closing),p_note:note})} onSaved={saved} submit="套用至官網與預約"><div className="form-grid"><Field label="日期"><input type="date" required disabled={!!value?.business_date} value={day} onChange={e=>setDay(e.target.value)}/></Field><Field label="狀態"><select value={String(isOpen)} onChange={e=>setOpen(e.target.value==='true')}><option value="true">營業</option><option value="false">休假／不開放預約</option></select></Field>{isOpen&&<><Field label="開始"><select value={opening} onChange={e=>{const n=Number(e.target.value);setOpening(n);if(n>=closing)setClosing(Math.min(2880,n+60));}}>{timeChoices.slice(0,49).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field><Field label="結束（可至翌日）"><select value={closing} onChange={e=>setClosing(Number(e.target.value))}>{timeChoices.filter(n=>n>opening).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field></>}<Field wide label="說明"><input maxLength="500" placeholder={isOpen?'例如：節日延長營業':'例如：店休'} value={note} onChange={e=>setNote(e.target.value)}/></Field></div><p className="muted">此設定不會取消既有預約；休假後官網不會再產生該日新空檔。</p></MutationForm>{hasOverride&&<div className="os-restore-hours"><button type="button" disabled={restoreBusy} onClick={restore}>恢復每週時間</button>{restoreError&&<p className="alert" role="alert">{restoreError}</p>}</div>}</>;
}

const resetScopes={appointments:['預約、完成數與療程收款','連動清除預約、結帳、評價、預約憑證及相關儲值／套票／現金流水；已扣點數或堂數會回復。'],orders:['商品訂單','連動清除訂單明細、訂單庫存變動與商品收款，售出庫存會回補。'],reviews:['評價與匿名建議','單獨清除所選期間建立的評價和建議。'],payroll:['薪資與工時','連動清除薪資結算、工時、加班與薪資調整。'],expenses:['門店支出','單獨清除所選期間記錄的費用支出。'],all:['全部營運記錄','組合以上範圍；保留會員檔案及儲值／套票購買記錄、員工帳號、療程商品、庫存主資料與系統設定。']};
function resetRange(mode){const today=taipeiDate();if(mode==='all')return {from:null,to:null};if(mode==='today')return {from:today,to:today};if(mode==='week'){const dow=new Date(`${today}T00:00:00Z`).getUTCDay();const from=dateAfter(-(dow===0?6:dow-1),today);return {from,to:dateAfter(6,from)};}const from=today.slice(0,8)+'01';const month=Number(today.slice(5,7)),year=Number(today.slice(0,4));const last=new Date(Date.UTC(year,month,0)).getUTCDate();return {from,to:`${today.slice(0,8)}${String(last).padStart(2,'0')}`};}
function downloadJson(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function ResetDataPanel({onReload}){
 const [scope,setScope]=useState('appointments'),[period,setPeriod]=useState('today'),[preview,setPreview]=useState(null),[confirm,setConfirm]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[done,setDone]=useState('');
 const range=resetRange(period),args={p_scope:scope,p_from:range.from,p_to:range.to};
 async function prepare(){setBusy(true);setError('');setDone('');try{setPreview(await rpc('spa_reset_preview',args));setConfirm('');}catch(e){setError(errorText(e));}finally{setBusy(false);}}
 async function execute(save){if(confirm!=='RESET')return;setBusy(true);setError('');try{if(save){const backup=await rpc('spa_backup_export',args);downloadJson(`ROU-SPA-backup-${scope}-${range.from||'all'}-${range.to||'all'}.json`,backup);}await rpc('spa_reset_business_data',{...args,p_confirmation:'RESET'});setPreview(null);setConfirm('');setDone('重設完成，營運統計已重新計算。');await onReload();}catch(e){setError(errorText(e));}finally{setBusy(false);}}
 return <section className="card os-danger-zone"><div className="os-page-title"><div><p className="eyebrow">OWNER CONTROL</p><h2>資料重設</h2><p className="muted">先選擇業務範圍與期間。有關聯的資料會作為一個完整鏈條重設，避免留下錯誤餘額或孤立記錄。</p></div></div><div className="form-grid"><Field label="重設內容"><select value={scope} onChange={e=>{setScope(e.target.value);setPreview(null);}}>{Object.entries(resetScopes).map(([id,[label]])=><option value={id} key={id}>{label}</option>)}</select></Field><Field label="日期範圍"><select value={period} onChange={e=>{setPeriod(e.target.value);setPreview(null);}}><option value="today">今天</option><option value="week">這個星期</option><option value="month">這個月</option><option value="all">全部期間</option></select></Field></div><p>{resetScopes[scope][1]}</p><p className="muted">範圍：{range.from?`${range.from} ～ ${range.to}`:'全部期間'}。會員檔案與儲值／套票購買記錄、員工與帳號、療程商品、庫存主資料、門店設定會保留；與被重設預約關聯的扣用會同步回復。</p><button className="danger" disabled={busy} onClick={prepare}>{busy?'檢查中…':'檢查重設範圍'}</button>{done&&<p className="success" role="status">{done}</p>}{error&&<p className="alert" role="alert">{error}</p>}{preview&&<Modal title="確認資料重設" onClose={()=>setPreview(null)}><p className="alert">這是不可復原的刪除操作。請選擇是否先下載 JSON 備份。</p><div className="os-reset-counts">{Object.entries(preview.counts).filter(([,n])=>Number(n)>0).map(([key,n])=><div key={key}><span>{({appointments:'預約',orders:'訂單',reviews:'評價',feedback:'匿名建議',payroll_runs:'薪資結算',time_entries:'工時／加班／調整',expenses:'支出'})[key]||key}</span><strong>{n}</strong></div>)}{!Object.values(preview.counts).some(Number)&&<Empty>此範圍沒有可重設記錄。</Empty>}</div><Field label="輸入 RESET 確認"><input autoComplete="off" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="RESET"/></Field><div className="actions"><button className="primary" type="button" disabled={busy||confirm!=='RESET'} onClick={()=>execute(true)}>先儲存備份，再重設</button><button className="danger" type="button" disabled={busy||confirm!=='RESET'} onClick={()=>execute(false)}>不儲存，直接重設</button></div>{error&&<p className="alert" role="alert">{error}</p>}</Modal>}</section>;
}

function JsonSettingForm({settingKey,value,fields,saved}){const [f,setF]=useState(value);return <MutationForm action={()=>rpc('spa_business_setting_save',{p_key:settingKey,p_value:f})} onSaved={saved}>{fields.map(([key,label])=><Field key={key} label={label}><input required value={f[key]||''} onChange={e=>setF({...f,[key]:e.target.value})}/></Field>)}</MutationForm>}
function WebsiteSettingForm({value,saved}){const [f,setF]=useState(value);return <MutationForm action={()=>rpc('spa_business_setting_save',{p_key:'website',p_value:f})} onSaved={saved}><Field label="LINE 網址"><input type="url" value={f.line_url||''} onChange={e=>setF({...f,line_url:e.target.value})}/></Field>{[['booking_cta','顯示預約按鈕'],['show_staff','顯示人員'],['show_products','顯示商品']].map(([key,label])=><label className="row" key={key}><input type="checkbox" checked={!!f[key]} onChange={e=>setF({...f,[key]:e.target.checked})}/>{label}</label>)}</MutationForm>}
function InventorySettingForm({value,saved}){const [behavior,setBehavior]=useState(value.zero_stock_behavior||'sold_out');return <MutationForm action={()=>rpc('spa_business_setting_save',{p_key:'inventory',p_value:{...value,zero_stock_behavior:behavior}})} onSaved={saved}><Field label="零庫存商品"><select value={behavior} onChange={e=>setBehavior(e.target.value)}><option value="sold_out">保留並標示售罄</option><option value="hide">自動隱藏</option></select></Field></MutationForm>}
function BookingSettingForm({value,saved}){const [days,setDays]=useState(value.booking_days),[auto,setAuto]=useState(value.auto_confirm),[cancel,setCancel]=useState(value.cancellation_hours);return <MutationForm action={()=>rpc('spa_settings_save',{p_open:Number(value.opening_minute),p_close:Number(value.closing_minute),p_days:Number(days),p_auto:auto,p_cancel:Number(cancel)})} onSaved={saved}><Field label="可預約天數"><input type="number" min="1" max="365" value={days} onChange={e=>setDays(e.target.value)}/></Field><Field label="預約確認"><select value={String(auto)} onChange={e=>setAuto(e.target.value==='true')}><option value="true">自動確認</option><option value="false">人工確認</option></select></Field><Field label="取消期限（小時）"><input type="number" min="0" max="720" value={cancel} onChange={e=>setCancel(e.target.value)}/></Field></MutationForm>}
function ResourceForm({row,saved}){const [name,setName]=useState(row?.name||''),[active,setActive]=useState(row?.active??true);return <MutationForm action={()=>rpc('spa_room_save',{p_id:row?.id||null,p_name:name,p_active:active})} onSaved={saved}><Field label="床位名稱"><input required value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="狀態"><select value={String(active)} onChange={e=>setActive(e.target.value==='true')}><option value="true">啟用</option><option value="false">停用</option></select></Field></MutationForm>}

export function PosOS({catalog,customers,onReload}){
 const products=catalog.products.filter(x=>x.status==='active'&&Number(x.inventory)>0),[cart,setCart]=useState([]),[customer,setCustomer]=useState(''),[method,setMethod]=useState('cash'),[discount,setDiscount]=useState('0'),[note,setNote]=useState(''),[done,setDone]=useState('');
 const add=product=>setCart(items=>{const found=items.find(x=>x.id===product.id);return found?items.map(x=>x.id===product.id?{...x,quantity:Math.min(Number(product.inventory),x.quantity+1)}:x):[...items,{...product,quantity:1}];});
 const total=cart.reduce((n,x)=>n+Number(x.price_cents)*x.quantity,0)-cents(discount||0);
 return <><div className="os-page-title"><div><h2>門店 POS</h2><p className="muted">商品價格與庫存直接使用目錄主資料；成交後自動扣庫存並保存售價快照。</p></div></div>{done&&<p className="success" role="status">完成收款：{done}</p>}<div className="split os-pos"><section><div className="grid">{products.map(p=><button className="card os-product-button" key={p.id} onClick={()=>add(p)}><strong>{p.name}</strong><span>{money(p.price_cents)}</span><small>庫存 {p.inventory} {p.unit_label}</small></button>)}</div></section><section className="card"><h2>本次銷售</h2>{!cart.length&&<Empty>點選左側商品加入銷售。</Empty>}{cart.map(item=><div className="os-cart-row" key={item.id}><span>{item.name}<small>{money(item.price_cents)} × {item.quantity}</small></span><div className="row"><button onClick={()=>setCart(cart.map(x=>x.id===item.id?{...x,quantity:Math.max(1,x.quantity-1)}:x))}>−</button><button onClick={()=>setCart(cart.map(x=>x.id===item.id?{...x,quantity:Math.min(Number(x.inventory),x.quantity+1)}:x))}>＋</button><button onClick={()=>setCart(cart.filter(x=>x.id!==item.id))}>移除</button></div></div>)}<Field label="會員（可不選）"><select value={customer} onChange={e=>setCustomer(e.target.value)}><option value="">散客</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name} · {c.phone}</option>)}</select></Field><Field label="折扣 NT$"><input type="number" min="0" step="0.01" value={discount} onChange={e=>setDiscount(e.target.value)}/></Field><Field label="收款方式"><select value={method} onChange={e=>setMethod(e.target.value)}><option value="cash">現金</option><option value="card">刷卡</option><option value="transfer">轉帳</option></select></Field><Field label="備註"><textarea value={note} onChange={e=>setNote(e.target.value)}/></Field><div className="metric">應收 {money(Math.max(0,total))}</div><button className="primary" disabled={!cart.length||total<0} onClick={async()=>{const sale=await rpc('spa_pos_checkout',{p_request:crypto.randomUUID(),p_customer:customer||null,p_items:cart.map(x=>({product_id:x.id,quantity:x.quantity,staff_id:null})),p_discount:cents(discount||0),p_method:method,p_note:note});setDone(`${sale.reference} · ${money(sale.total_cents)}`);setCart([]);setDiscount('0');setNote('');await onReload();}}>確認收款</button></section></div></>;
}
